def max_product(arr):
    """
    :param arr: list[int]
    :return: int
    """
    if len(arr) < 2:
        return 0

    max_product = arr[0]
    min_product = arr[0]

    for i in range(1, len(arr)):
        if arr[i] < 0:
            max_product, min_product = min_product, max_product

