def get_median(list1, list2, k):
    """
    :param list1: list1[int]
    :param list2: list2[int]
    :param k: int
    :return: float
    """
    if len(list1) > len(list2):
        list1, list2 = list2, list1
        k = len(list1)
    if k == 0:
        raise ValueError("k cannot be 0")
    if k == 1:
        return min(list1[0], list2[0])
    if k % 2 == 0:
        return (min(list1[k//2], list2[k//2]) + max(list1[k//2-1], list2[k//2-1])) / 2
    else:
        return max(list1[k//2], list2[k//2])

