def last(arr,x):
    if len(arr) == 0:
        return -1
    if len(arr) == 1:
        if arr[0] == x:
            return 0
        else:
            return -1
    if arr[0] == x:
        return 0
    if arr[len(arr)-1] == x:
        return len(arr)-1
    if arr[0] < x:
        return last(arr[1:],x)
    if arr[len(arr)-1] > x:
        return last(arr[:len(arr)-1],x)
    return -1

